import sys,collections,heapq,itertools,functools,bisect
def solve(data):
    v=list(map(int,data.split()));a=[v[i*4:i*4+4] for i in range(4)];row=[0]*4;col=[0]*4;box=[0]*4
    for i in range(4):
        for j in range(4):
            if a[i][j]:
                b=i//2*2+j//2;x=1<<(a[i][j]-1)
                if (row[i]|col[j]|box[b])&x:return 0
                row[i]|=x;col[j]|=x;box[b]|=x
    def f(p):
        if p==16:return 1
        i,j=divmod(p,4);b=i//2*2+j//2
        if a[i][j]:return f(p+1)
        ans=0;v=15&~(row[i]|col[j]|box[b])
        while v:
            x=v&-v;v-=x;row[i]|=x;col[j]|=x;box[b]|=x;ans+=f(p+1);row[i]^=x;col[j]^=x;box[b]^=x
        return ans
    return f(0)

if __name__=="__main__":
    a=solve(sys.stdin.buffer.read().decode())
    print(" ".join(map(str,a)) if isinstance(a,(list,tuple)) else a)
